class Solution {
    public int maxWindowSum(int[] nums, int k) {
        int windowSum = 0;
        for (int i = 0; i < k; i++) windowSum += nums[i];
        int best = windowSum;
        for (int r = k; r < nums.length; r++) {
            windowSum += nums[r] - nums[r - k];
            best = Math.max(best, windowSum);
        }
        return best;
    }
}

